inline constexpr std::size_t DescriptorCount = sizeof(kDescriptors) / sizeof(kDescriptors[0]);

inline bool Equal(StringView left, StringView right) noexcept
{
    if (left.size != right.size) return false;
    for (std::uint32_t i = 0; i < left.size; ++i)
        if (left.data[i] != right.data[i]) return false;
    return true;
}

inline const DescriptorView* FindByCanonicalKey(StringView key) noexcept
{
    for (const DescriptorView& descriptor : kDescriptors)
        if (Equal(descriptor.canonical_key, key)) return &descriptor;
    return nullptr;
}

inline const DescriptorView* FindByDisplayCode(StringView code) noexcept
{
    for (const DescriptorView& descriptor : kDescriptors)
    {
        if (descriptor.display_code.size != 0 && Equal(descriptor.display_code, code)) return &descriptor;
        for (std::uint16_t i = 0; i < descriptor.alias_count; ++i)
            if (Equal(descriptor.aliases[i], code)) return &descriptor;
    }
    return nullptr;
}

inline bool FindParameter(const Occurrence& occurrence, StringView name, StringView& value) noexcept
{
    for (std::uint16_t i = 0; i < occurrence.parameter_count; ++i)
        if (Equal(occurrence.parameters[i].name, name)) { value = occurrence.parameters[i].value; return true; }
    return false;
}

inline void AppendChar(char* buffer, std::size_t capacity, std::size_t& size, char value) noexcept
{
    if (buffer != nullptr && size < capacity) buffer[size] = value;
    ++size;
}

inline void AppendText(char* buffer, std::size_t capacity, std::size_t& size, StringView value) noexcept
{
    for (std::uint32_t i = 0; i < value.size; ++i) AppendChar(buffer, capacity, size, value.data[i]);
}

inline void AppendNumber(char* buffer, std::size_t capacity, std::size_t& size, std::uint32_t value) noexcept
{
    char digits[10]; std::uint32_t count = 0;
    do { digits[count++] = static_cast<char>('0' + (value % 10)); value /= 10; } while (value != 0);
    while (count != 0) AppendChar(buffer, capacity, size, digits[--count]);
}

inline void AppendTemplate(char* buffer, std::size_t capacity, std::size_t& size, StringView value, const Occurrence& occurrence) noexcept
{
    for (std::uint32_t i = 0; i < value.size;)
    {
        if (value.data[i] != '{') { AppendChar(buffer, capacity, size, value.data[i++]); continue; }
        std::uint32_t end = i + 1; while (end < value.size && value.data[end] != '}') ++end;
        if (end == value.size) { AppendChar(buffer, capacity, size, value.data[i++]); continue; }
        StringView name{value.data + i + 1, end - i - 1}; StringView replacement{};
        if (FindParameter(occurrence, name, replacement)) AppendText(buffer, capacity, size, replacement);
        else for (std::uint32_t part = i; part <= end; ++part) AppendChar(buffer, capacity, size, value.data[part]);
        i = end + 1;
    }
}

inline FormatResult FormatOccurrence(const Occurrence& occurrence, char* buffer, std::size_t capacity) noexcept
{
    if (occurrence.descriptor == nullptr) return FormatResult{0, false};
    const DescriptorView& descriptor = *occurrence.descriptor; std::size_t size = 0;
    AppendText(buffer, capacity, size, Literal("key: ")); AppendText(buffer, capacity, size, descriptor.canonical_key); AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("code: ")); AppendText(buffer, capacity, size, descriptor.display_code); AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("location: ")); AppendText(buffer, capacity, size, occurrence.primary_location.uri);
    if (occurrence.primary_location.line != 0) { AppendChar(buffer, capacity, size, ':'); AppendNumber(buffer, capacity, size, occurrence.primary_location.line); }
    if (occurrence.primary_location.column != 0) { AppendChar(buffer, capacity, size, ':'); AppendNumber(buffer, capacity, size, occurrence.primary_location.column); }
    AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("what: ")); AppendTemplate(buffer, capacity, size, descriptor.what_template, occurrence); AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("why: ")); AppendTemplate(buffer, capacity, size, descriptor.why_template, occurrence); AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("fix: ")); AppendTemplate(buffer, capacity, size, descriptor.fix_template, occurrence); AppendChar(buffer, capacity, size, '\n');
    AppendText(buffer, capacity, size, Literal("doc: ")); AppendText(buffer, capacity, size, descriptor.doc_anchor); AppendChar(buffer, capacity, size, '\n');
    if (buffer != nullptr && capacity != 0) buffer[size < capacity ? size : capacity - 1] = '\0';
    return FormatResult{size, buffer != nullptr && capacity > size};
}
